import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { TranslocoPipe } from '@jsverse/transloco';
import { AppStateService } from '@shared/context/state/app-state.service';

/** Estados con texto e imagen propios; el resto de 4xx cae en `error_unknown` y los 5xx en `error_5xx`. */
const KNOWN_STATUS = [0, 401, 402, 403, 404, 409, 422];

export interface ErrorDescription {
  /** Clave bajo `errors.page`: `error_404`, `no_empty_error_422`, `error_5xx`, `error_unknown`, `no_content`. */
  kind: string;
  image: string;
  /** Detalle técnico para soporte (solo se muestra plegado). */
  detail: string | null;
  traceId: string | null;
}

export function describeError(error: any): ErrorDescription {
  if (!error) {
    return { kind: 'no_content', image: 'no-section.png', detail: null, traceId: null };
  }
  const status: number | undefined = typeof error.status === 'number' ? error.status : undefined;
  const notEmpty = error.error?.[0]?.description === 'not-empty';
  let kind = 'error_unknown';
  let image = 'error-unknown.png';
  if (status !== undefined && KNOWN_STATUS.includes(status)) {
    kind = (notEmpty ? 'no_empty_' : '') + 'error_' + status;
    image = 'error-' + status + (notEmpty ? '-no-empty' : '') + '.png';
  } else if (status !== undefined && status >= 500) {
    kind = 'error_5xx';
  }
  return { kind, image, detail: technicalDetail(error, status), traceId: error.traceId ?? null };
}

function technicalDetail(error: any, status: number | undefined): string | null {
  const payload = error.error;
  const message =
    typeof payload === 'string'
      ? payload
      : (payload?.message ?? (payload != null ? JSON.stringify(payload) : (error.message ?? null)));
  const parts = [status !== undefined ? 'HTTP ' + status : null, error.url ?? null, message].filter((p) => !!p);
  return parts.length ? parts.join(' · ') : null;
}

@Component({
  selector: 'app-page-error',
  standalone: true,
  imports: [RouterLink, MatButtonModule, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './error-page.component.html',
  styleUrl: './error-page.component.scss',
})
export class ErrorPageComponent {
  private readonly state = inject(AppStateService);

  readonly error = input<any>();
  readonly asColumn = input(false);
  /** Sustituyen al título y al mensaje según el estado (p. ej. la página de acceso denegado). */
  readonly titleKey = input<string>();
  readonly messageKey = input<string>();
  readonly showHome = input(true);
  /** El modal de error lo pinta como título del diálogo. */
  readonly showTitle = input(true);

  readonly description = computed(() => describeError(this.error()));
  readonly title = computed(() => this.titleKey() ?? 'errors.page.' + this.description().kind + '.title');
  readonly message = computed(() => this.messageKey() ?? 'errors.page.' + this.description().kind + '.message');

  private readonly language = this.state.language;
  private readonly tenant = this.state.tenant;
  readonly home = computed(() => ['/', this.language(), this.tenant()]);
}
